Here is the commit message:
powerpc/pseries: Fix potential memleak in papr_get_attr()

`buf` is allocated in papr_get_attr(), and krealloc() of `buf`
could fail. We need to free the original `buf` in the case of failure.

Fixes: 3c14b73454cf ("powerpc/pseries: Interface to represent PAPR firmware attributes")
Signed-off-by: Qiheng Lin <linqiheng@huawei.com>
Signed-off-by: Michael Ellerman <mpe@ellerman.id.au>
Link: https://msgid.link/20221208133449.16284-1-linqiheng@huawei.com

Here is the root cause:
The bug is caused by the failure of the `krealloc()` function, which reallocates memory for the buffer `buf`. If `krealloc()` fails, it returns `NULL`, and the original buffer is not freed, leading to a potential memory leak. The code did not previously handle this failure case properly, resulting in the original buffer remaining allocated without being released.

Here is the patch:
  */
 static int papr_get_attr(u64 id, struct energy_scale_attribute *esi)
 {
 	int esi_buf_size = ESI_HDR_SIZE + (CURR_MAX_ESI_ATTRS * ESI_ATTR_SIZE);
 	int ret, max_esi_attrs = CURR_MAX_ESI_ATTRS;
 	struct energy_scale_attribute *curr_esi;
 	struct h_energy_scale_info_hdr *hdr;
 	char *buf;

 	buf = kmalloc(esi_buf_size, GFP_KERNEL);
 	if (buf == NULL)
 		return -ENOMEM;

 retry:
 	ret = plpar_hcall_norets(H_GET_ENERGY_SCALE_INFO, ESI_FLAGS_SINGLE,
 				 id, virt_to_phys(buf),
 				 esi_buf_size);

 	/*
 	 * If the hcall fails with not enough memory for either the
 	 * header or data, attempt to allocate more
 	 */
 	if (ret == H_PARTIAL || ret == H_P4) {
 		char *temp_buf;

 		max_esi_attrs += 4;
 		esi_buf_size = ESI_HDR_SIZE + (CURR_MAX_ESI_ATTRS * max_esi_attrs);

 		temp_buf = krealloc(buf, esi_buf_size, GFP_KERNEL);
-		if (temp_buf)
+		if (temp_buf) {
 			buf = temp_buf;
-		else
-			return -ENOMEM;
+		} else {
+			ret = -ENOMEM;
+			goto out_buf;
+		}

 		goto retry;
 	}

 	if (ret != H_SUCCESS) {
 		pr_warn("hcall failed: H_GET_ENERGY_SCALE_INFO");
 		ret = -EIO;
 		goto out_buf;
 	}

 	hdr = (struct h_energy_scale_info_hdr *) buf;
 	curr_esi = (struct energy_scale_attribute *)
 		(buf + be64_to_cpu(hdr->array_offset));

 	if (esi_buf_size <
 	    be64_to_cpu(hdr->array_offset) + (be64_to_cpu(hdr->num_attrs)
 	    * sizeof(struct energy_scale_attribute))) {
 		ret = -EIO;
 		goto out_buf;
 	}

 	*esi = *curr_esi;

 out_buf:
 	kfree(buf);

 	return ret;
 }



